const input = $json;
const messages = (input.conversation ?? []).filter((message) => message.role === 'user');
const text = messages.map((message) => String(message.content ?? '').toLocaleLowerCase()).join(' ');
const catalog = input.catalog ?? {};
const scores = (catalog.intents ?? []).map((intent) => {
  let score = 0;
  for (const signal of (catalog.signals ?? []).filter((candidate) => candidate.intentKey === intent.intentKey)) {
    const value = String(signal.value ?? '').toLocaleLowerCase();
    if (value && text.includes(value)) score += Number(signal.weight ?? 0);
  }
  return { intentKey: intent.intentKey, score, priority: Number(intent.priority ?? 0), category: String(intent.category ?? '').toLocaleLowerCase() };
}).filter((item) => item.score > 0).sort((a, b) => b.score - a.score || b.priority - a.priority);
const primary = scores[0]?.intentKey ?? input.intent;
const secondary = scores.slice(1).filter((item) => item.score >= Math.max(10, (scores[0]?.score ?? 0) * 0.35)).map((item) => item.intentKey);
const optedOut = /do not contact|don't contact|no contact|unsubscribe|لا تتصل|لا تواصل/i.test(text);
const supportOnly = scores.length > 0 && scores.every((item) => /support|renew|licen[cs]|portal|regulat|amend/i.test(`${item.category} ${item.intentKey}`));
const commercial = !supportOnly && !optedOut && scores.some((item) => /sales|commercial|company|setup|visa|it|quote|demo|call|service/i.test(`${item.category} ${item.intentKey}`));
return [{ json: { ...input, primaryIntent: primary, secondaryIntents: secondary, route: optedOut ? 'opt_out' : supportOnly ? 'support' : commercial ? 'commercial' : 'human_review' } }];

const input = $json;
const messages = (input.conversation ?? []).filter((message) => message.role === 'user');
const latest = (kind) => messages.flatMap((message) => String(message.content ?? '').match(new RegExp('\\[' + kind + '_\\d+\\]', 'g')) ?? []).at(-1);
const leadData = { ...(input.leadData ?? {}) };
for (const kind of ['NAME', 'EMAIL', 'PHONE']) { const token = latest(kind); if (token) leadData[kind.toLowerCase()] = token; }
return [{ json: { ...input, leadData, remoteCrm: $env.REMOTE_CRM_PROVIDER || '' } }];

const input = $('Extract and Merge Lead Fields').first().json;
const stored = $json;
const users = (input.conversation ?? []).filter((message) => message.role === 'user');
const text = users.map((message) => String(message.content ?? '').toLocaleLowerCase()).join(' ');
const commercialIntent = Number(input.intentScore ?? 0) >= Number((input.catalog?.intents ?? []).find((item) => item.intentKey === (input.primaryIntent || input.intent))?.minimumScore ?? 0) ? 25 : 0;
const timeline = /urgent|asap|today|this month|next month|عاجل|هذا الشهر/i.test(text) ? 20 : 0;
const businessFit = /business|company|requirements?|module|visa|shareholder|office|budget|erp|it|commercial|نشاط|شركة|متطلبات/i.test(text) ? 20 : 0;
const contactQuality = input.leadData?.email && input.leadData?.phone ? 20 : (input.leadData?.email || input.leadData?.phone) ? 15 : 0;
const engagement = Math.min(15, users.length * 3);
const score = Math.max(0, Math.min(100, commercialIntent + timeline + businessFit + contactQuality + engagement));
const summary = `Intent: ${input.primaryIntent || input.intent}. Secondary intents: ${(input.secondaryIntents ?? []).join(', ') || 'none'}. Visitor supplied ${users.length} user turns. Qualification score: ${score}/100.`;
return [{ json: { ...input, leadId: stored.lead?.id, score, summary, qualityWorkflowKey: input.qualityWorkflowKey || null } }];

const source = $('Lead Scoring and Summary').first().json;
const stored = $json;
return [{ json: { ...source, leadId: stored.lead?.id ?? source.leadId, score: stored.lead?.score ?? source.score } }];

const result = $json;
const pattern = $env.REMOTE_CRM_LEAD_ID_PATTERN || '^[A-Za-z0-9._:-]{1,200}$';
if (typeof result.leadId !== 'string' || !new RegExp(pattern).test(result.leadId)) throw new Error('Remote CRM did not return a valid lead ID.');
return [{ json: { ...$('Lead Scoring and Summary').first().json, remoteLeadId: result.leadId, remoteCrm: $('Lead Scoring and Summary').first().json.remoteCrm } }];

const source = $('Lead Scoring and Summary').first().json;
const remote = $('Validate Remote CRM Lead ID').first().json;
return [{ json: { accepted: true, status: 'registered', actionId: source.actionId, leadId: remote.remoteLeadId, remoteCrm: remote.remoteCrm, message: 'Your request is registered. We will continue processing it asynchronously.' } }];
